import {useRouteQuery} from '@github-ui/react-core/future/use-route-query'
import {definitionsIndexRoute} from './definitions-index-route'

import {Blankslate} from '@primer/react/experimental'
import {useParams} from '@github-ui/react-router'
import {getDefinitionDetailsPath, getDefinitionListPath} from '../paths'
import {DefinitionsTable} from '@github-ui/stafftools-custom-properties-core/definitions/table'

export function DefinitionsIndex() {
  const {data} = useRouteQuery(definitionsIndexRoute, 'mainQuery')
  const {enterprise} = useParams()

  const tableData = data.definitions.map(definition => ({
    ...definition,
    id: definition.name,
  }))

  if (tableData.length === 0) {
    return (
      <Blankslate border>
        <Blankslate.Heading>No definitions defined on this enterprise</Blankslate.Heading>
      </Blankslate>
    )
  }

  return (
    <DefinitionsTable
      data={tableData}
      source={enterprise || ''}
      getDefinitionDetailsPath={getDefinitionDetailsPath}
      getDefinitionListPath={getDefinitionListPath}
    />
  )
}
